"""Metadata processing for report-ledger."""

import json
import re
from datetime import date

_DAY_PATTERN = re.compile(r'\d{4}-\d{2}-\d{2}', re.ASCII)


def _parse_day(value):
    if not isinstance(value, str) or not _DAY_PATTERN.fullmatch(value):
        raise ValueError('day must be a YYYY-MM-DD string')
    year, month, day = (int(part) for part in value.split('-'))
    try:
        return date(year, month, day)
    except ValueError as exc:
        raise ValueError(f'day is not a real calendar date: {value}') from exc


def _parse_amount_cents(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError('amount_cents must be an integer')
    return value


def _parse_row(value):
    if not isinstance(value, dict):
        raise ValueError('each row must be a JSON object')
    tenant = value.get('tenant')
    if not isinstance(tenant, str) or not tenant:
        raise ValueError('tenant must be a nonempty string')
    return _parse_amount_cents(value.get('amount_cents')), _parse_day(value.get('day'))


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        rows = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError(f'malformed JSON: {exc}') from exc
    if not isinstance(rows, list):
        raise ValueError('input must be a JSON array of rows')

    total_cents = 0
    first_day = None
    last_day = None
    for row in rows:
        amount_cents, day = _parse_row(row)
        total_cents += amount_cents
        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day

    return {
        'row_count': len(rows),
        'total_cents': total_cents,
        'first_day': first_day.isoformat() if first_day is not None else None,
        'last_day': last_day.isoformat() if last_day is not None else None,
    }
